class N351SpecificGateControllerNode(BrainNode):
    """Node 351: 丘脑中继站·Afferent·Ipsilateral·Crossed·Ascending·SpecGate

    Folder: L08_Ascending--SpecificGateController
    Layer: L08
    Region: relay
    Responsibility: 特异性门控器，选择性传递信号
    """
    def process(self, data: BrainData) -> BrainData:
        """特异性门控器，选择性传递信号"""
        # Signal relay with optional gating
        gate_open = self.get_state("gate_open", True)
        if not gate_open:
            if isinstance(data, Tensor):
                return Tensor.zeros(data.data.shape)
            elif isinstance(data, Signal):
                return Signal(value=0.0, timestamp=data.timestamp)
            return data
        # Relay with gain
        gain = self.get_state("relay_gain", 1.0)
        if isinstance(data, Tensor):
            return Tensor(data=data.data * gain, shape=data.data.shape)
        elif isinstance(data, Signal):
            return Signal(value=data.value * gain, timestamp=data.timestamp)
        return data



